function matchBackgroundRule(scene, rules = []) {
    const candidates = rules
        .filter((rule) => matchesRule(scene, rule.match || {}))
        .sort((a, b) => (b.priority || 0) - (a.priority || 0));

    return candidates[0] || null;
}

