        const stamp = `${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`;
        const res = await globalObject.fetch('/api/files/upload', {
            method: 'POST',
            headers,
            body: JSON.stringify({ name: `igs-bgm-${stamp}.${ext}`, data: base64Of(bytes) }),
        });
