    const names = [entry.label, ...String(entry.label || '').split(/\s*\/\s*/)].map(normalize).filter(Boolean);
    const nodes = [...body.querySelectorAll('label, b, strong, span, small, summary, h3, h4, button, .igs-perf-item-head')];
