__igsRegister("src/visual/igs-ui/meta-fields.js", function(module, exports, require) {
const { esc } = require("src/visual/igs-ui/reader-value-utils.js");
const { checkbox, field, segmentedInput, textInput } = require("src/visual/igs-ui/settings-fields.js");
const { collapsible, featureRow, perfSubhead } = require("src/visual/igs-ui/fx-settings-fields.js");
const { META_COOLDOWNS, META_DEFAULT_LINES, META_GLOBAL_SCOPE, META_LINE_KINDS, META_LINE_LABELS, META_LINES_MAX, normalizeMetaFxSettings } = require("src/visual/igs-ui/meta-settings.js");
const { pendingMetaDigest } = require("src/visual/igs-ui/meta-digest.js");
const P = 'readerSettings.metaFx';
const encSeg = (value) => encodeURIComponent(String(value == null ? '' : value));

function sub(body) {
    return `<div class="igs-settings-sub">${body}</div>`;
}

// 台词池：未自定义时显示内置台词（灰字），添加第一句后改为只用自定义台词。
function linePool(scope, kind, lines) {
    const own = (lines[scope] && lines[scope][kind]) || [];
    const tags = own.map((line, index) => `<span class="igs-mood-word-tag">${esc(line)}<button type="button" class="igs-mood-word-del" data-action="meta-line-remove:${encSeg(scope)}:${kind}:${index}" title="删除">×</button></span>`).join('');
    const fallback = scope === META_GLOBAL_SCOPE ? `内置：${META_DEFAULT_LINES[kind].join(' / ')}` : '未自定义，沿用通用台词';
    const add = own.length < META_LINES_MAX ? `<button type="button" class="igs-btn-mgr-icon" data-action="meta-line-add:${encSeg(scope)}:${kind}" title="添加台词">+</button>` : '';
    return `<div class="igs-settings-field"><span>${esc(META_LINE_LABELS[kind])}</span><div class="igs-mood-word-list">${tags || `<div class="igs-scene-empty">${esc(fallback)}</div>`}${add}</div></div>`;
}

function scopeBlock(scope, lines) {
    const title = scope === META_GLOBAL_SCOPE ? '通用' : scope;
    const remove = scope === META_GLOBAL_SCOPE ? '' : `<button type="button" class="igs-btn-mgr-icon" data-action="meta-scope-remove:${encSeg(scope)}" title="删除该角色的台词">×</button>`;
    return `<div class="igs-source-filter-title">${esc(title)}${remove}</div>` + META_LINE_KINDS.map((kind) => linePool(scope, kind, lines)).join('');
}

// Meta 互动的设置片段：独立开关，不参与一键档位；关闭时已保存的子设置保留不清空。
function renderMetaFxFields(reader, more = collapsible) {
    const s = normalizeMetaFxSettings(reader && reader.metaFx);
    const hint = '角色察觉屏幕前的你';
    if (!s.enabled) return featureRow(more, 'meta', `${P}.enabled`, false, 'Meta互动', hint);
    const touch = checkbox(`${P}.poke`, s.poke, '戳立绘头部')
        + checkbox(`${P}.hover`, s.hover, '鼠标悬停头部（电脑端）');
    const reading = checkbox(`${P}.reading`, s.reading, '阅读行为吐槽')
        + field(`${P}.cooldownSec`, '吐槽间隔', segmentedInput(`${P}.cooldownSec`, String(s.cooldownSec), META_COOLDOWNS.map((n) => [String(n), `${n} 秒`]), '吐槽间隔'));
    const clock = checkbox(`${P}.clock`, s.clock, '真实时间问候')
        + (s.clock ? sub(checkbox(`${P}.festivals`, s.festivals, '节日问候')
            + field(`${P}.birthday`, '你的生日', textInput(`${P}.birthday`, s.birthday, '如03-05，留空不启用'))) : '');
    const preview = pendingMetaDigest();
    const digest = checkbox(`${P}.digest`, s.digest, '发送时告诉AI本轮互动')
        + (s.digest ? sub(`<div class="igs-source-filter-note">只影响下一次生成，送出后清空。当前待送出：${esc(preview || '（暂无）')}</div>`) : '');
    const scopes = [META_GLOBAL_SCOPE, ...Object.keys(s.lines).filter((key) => key !== META_GLOBAL_SCOPE)];
    const lines = scopes.map((scope) => scopeBlock(scope, s.lines)).join('')
        + '<button type="button" class="igs-btn-mgr-icon" data-action="meta-scope-add" title="为某个角色单独设置台词">+ 角色</button>'
        + '<div class="igs-source-filter-note">角色台词优先，其次通用，再次内置；角色名需与立绘角色名一致。</div>';
    return featureRow(more, 'meta', `${P}.enabled`, true, 'Meta互动', hint, touch + reading + clock + digest + perfSubhead('台词') + lines);
}

__igsDefine(exports, "renderMetaFxFields", () => renderMetaFxFields);
});
__igsRegister("src/visual/igs-ui/meta-digest.js", function(module, exports, require) {
const { buildMetaDigestRule, normalizeMetaFxSettings, summarizeMetaEvents } = require("src/visual/igs-ui/meta-settings.js");
// 交互摘要暂存：阅读器记录事件，bootstrap 注入提示词。生成开始时记下已送出的条数，结束后只清掉这部分，
// 生成过程中新发生的事件留给下一轮。只存在内存里，不写进聊天记录。
const EVENTS_MAX = 50;
const events = [];
let sentCount = 0;
const listeners = new Set();

function notify() {
    for (const listener of listeners) {
        try { listener(); } catch (error) { /* */ }
    }
}
function recordMetaEvent(event) {
    if (!event || typeof event !== 'object') return;
    events.push({ ...event });
    while (events.length > EVENTS_MAX) {
        events.shift();
        sentCount = Math.max(0, sentCount - 1);
    }
    notify();
}
function pendingMetaDigest() {
    return summarizeMetaEvents(events);
}

// 原始事件副本：直播互动等其他模块据此拼自己的摘要，与 Meta 互动共用送出 / 清空节奏。
function pendingMetaEvents() {
    return events.map((event) => ({ ...event }));
}
function beginMetaDigestSend() {
    sentCount = events.length;
}
function finishMetaDigestSend() {
    if (!sentCount) return;
    events.splice(0, sentCount);
    sentCount = 0;
    notify();
}
function clearMetaDigest() {
    const had = events.length > 0;
    events.length = 0;
    sentCount = 0;
    if (had) notify();
}
function onMetaDigestChange(listener) {
    if (typeof listener !== 'function') return () => {};
    listeners.add(listener);
    return () => listeners.delete(listener);
}

// 总开关与摘要开关都开、且有待送出的事件时才返回规则。
function resolveMetaDigestRule(settings) {
    const s = normalizeMetaFxSettings(settings);
    if (!s.enabled || !s.digest) return '';
    return buildMetaDigestRule(pendingMetaDigest());
}

__igsDefine(exports, "recordMetaEvent", () => recordMetaEvent);
__igsDefine(exports, "pendingMetaDigest", () => pendingMetaDigest);
__igsDefine(exports, "pendingMetaEvents", () => pendingMetaEvents);
__igsDefine(exports, "beginMetaDigestSend", () => beginMetaDigestSend);
__igsDefine(exports, "finishMetaDigestSend", () => finishMetaDigestSend);
__igsDefine(exports, "clearMetaDigest", () => clearMetaDigest);
__igsDefine(exports, "onMetaDigestChange", () => onMetaDigestChange);
__igsDefine(exports, "resolveMetaDigestRule", () => resolveMetaDigestRule);
});
