const INDOOR_NIGHT_SCALE = 0.5;
const INDOOR_WEATHER_SCALE = 0.35;
const MAX_LAYER_AMOUNT = 0.95;
const LIMITS = Object.freeze({ c: [0.7, 1.15], s: [0.5, 1.25], b: [0.6, 1.12] });
