        + `<path class="igs-fx-rim" d="${d}" stroke-width="${(12 * k).toFixed(1)}"/>`
        + `<path class="igs-fx-fill" d="${d}" stroke-width="${(4.5 * k).toFixed(1)}"/>`
        + extra
