const LEAF_WORDS = Object.freeze(['秋', '枫', '红叶', '落叶', 'autumn', 'maple', 'fall foliage']);
// 「青春」「秋叶原」只是字面含春/秋，不代表季节。
const FALSE_FRIENDS = /青春|秋叶原|秋葉原/g;

