const ITEM_HOLDER_FIELDS = Object.freeze(['持有者', '所属角色', '拥有者', '穿戴者', '角色']);
const WORN_STATUS_WORDS = Object.freeze(['穿着', '正在穿', '已穿戴', '已装备', '装备中']);
