        return `<tr>${tds}<td class="igs-db-ro-cell"><button class="igs-db-del-btn" data-db-act="delete-row" data-db-row-index="${rowIdx}" data-db-row-id="${Number.isFinite(rowId) ? rowId : ''}">删除</button></td></tr>`;
